    // ====================================================================
    // TOP PATTERNS ANALYSIS
    // ====================================================================

    console.log(`\nTOP PATTERNS:`);
    const patternEntries = Object.entries(this.data.patterns);
    if (patternEntries.length > 0) {
      const sortedPatterns = patternEntries
        .sort((a, b) => b[1].totalPnL - a[1].totalPnL)
