            this.ws.send(message);
            console.log(`ðŸŸ¢ STARTER: ${action} @ $${this.currentPrice} | RSI: ${rsi.toFixed(1)} | MACD: ${macd.histogram.toFixed(2)} | Confidence: ${confidence}% | P&L: $${pnl.toFixed(2)}`);
        }
    }
}

