    this.riskLimits.emergencyStopActive = true;
    this.riskLimits.emergencyStopReason = reason;
    this.riskLimits.tradingHalted = true;
    this.riskLimits.haltReason = reason;

    console.log(`ðŸš¨ EMERGENCY STOP ACTIVATED: ${reason}`);
