      agreement: agreement,
      agreementLevel: agreement > 0.8 ? 'HIGH' : agreement > 0.6 ? 'MEDIUM' : 'LOW',
      approvedBy: verifications.filter((v, i) => Math.abs(v.result - mean) <= stdDev).map(v => v.method),
