            const steps = Math.floor((subRange.max - subRange.min) / subRange.step);
            const randomStep = Math.floor(Math.random() * (steps + 1));
            strategy[param][subParam] = subRange.min + (randomStep * subRange.step);
          }
        }
      }

      population.push(strategy);
    }

    return population;
  }

  /**
   * Test each strategy on historical data
   */
  async evaluatePopulation(population, historicalData) {
    const results = [];

    for (let i = 0; i < population.length; i++) {
      const strategy = population[i];
      process.stdout.write(`\rTesting strategy ${i + 1}/${population.length}...`);

      // Run backtest with these parameters
      const performance = await this.backtestStrategy(strategy, historicalData);

      // Calculate fitness based on optimization goal
      const fitness = this.calculateFitness(performance);

      results.push({
        strategy,
        performance,
        fitness
      });
    }

    console.log(' Done!');
    return results;
  }

  /**
   * Backtest a single strategy
   */
  async backtestStrategy(strategy, historicalData) {
    // Create a mock OGZ Prime instance with these parameters
    const testBot = {
      ...this.ogzPrime,
      config: {
        ...this.ogzPrime.config,
        ...strategy
      }
    };

    // Run through historical data
    let balance = 10000;
    const trades = [];
    let position = null;

    for (const candle of historicalData) {
      // Simplified backtest logic
      // In reality, you'd run the full analysis

      // Mock analysis
      const shouldBuy = Math.random() > 0.7 && !position;
      const shouldSell = Math.random() > 0.6 && position;

      if (shouldBuy) {
        position = {
          entryPrice: candle.close,
          size: (balance * strategy.riskPercentage / 100) / candle.close
        };
      } else if (shouldSell && position) {
        const pnl = (candle.close - position.entryPrice) * position.size;
        balance += pnl;
        trades.push({ pnl, profitable: pnl > 0 });
        position = null;
      }
    }

    // Calculate performance metrics
    const winningTrades = trades.filter(t => t.profitable).length;
    const totalPnL = balance - 10000;
    const winRate = trades.length > 0 ? winningTrades / trades.length : 0;

    // Calculate Sharpe ratio (simplified)
    const returns = trades.map(t => t.pnl / 10000);
    const avgReturn = returns.reduce((a, b) => a + b, 0) / returns.length || 0;
    const stdDev = Math.sqrt(
      returns.reduce((sum, r) => sum + Math.pow(r - avgReturn, 2), 0) / returns.length
    ) || 0.001;
    const sharpe = stdDev > 0 ? (avgReturn / stdDev) * Math.sqrt(365) : 0; // Crypto trades 365 days

    return {
      totalPnL,
      winRate,
      sharpe,
      trades: trades.length,
      maxDrawdown: this.calculateMaxDrawdown(trades)
    };
  }

  /**
   * Calculate fitness score based on optimization goal
   */
  calculateFitness(performance) {
    // Minimum trades requirement
    if (performance.trades < this.config.minTrades) {
      return 0;
    }

    switch (this.config.optimizeFor) {
      case 'profit':
        return performance.totalPnL / 10000; // Normalize

      case 'sharpe':
        return Math.max(0, performance.sharpe / 3); // Normalize (3 is excellent)

      case 'winrate':
        return performance.winRate;

      case 'balanced':
        // Combine multiple metrics
        const profitScore = Math.max(0, performance.totalPnL / 5000);
        const sharpeScore = Math.max(0, performance.sharpe / 2);
        const winRateScore = performance.winRate;
        const drawdownPenalty = Math.max(0, 1 - performance.maxDrawdown / 20);

        return (profitScore + sharpeScore + winRateScore + drawdownPenalty) / 4;

      default:
        return performance.totalPnL / 10000;
    }
  }

  /**
   * Create next generation through selection, crossover, and mutation
   */
  evolvePopulation(results) {
    const newPopulation = [];

    // Keep elite strategies
    for (let i = 0; i < this.config.eliteSize; i++) {
      newPopulation.push({ ...results[i].strategy });
    }

    // Create rest through crossover and mutation
    while (newPopulation.length < this.config.populationSize) {
      // Select parents (tournament selection)
      const parent1 = this.tournamentSelect(results);
      const parent2 = this.tournamentSelect(results);

      // Crossover
      const child = this.crossover(parent1.strategy, parent2.strategy);

      // Mutation
      if (Math.random() < this.config.mutationRate) {
        this.mutate(child);
      }

      newPopulation.push(child);
    }

    return newPopulation;
  }

  /**
   * Tournament selection
   */
  tournamentSelect(results, tournamentSize = 3) {
    let best = null;

    for (let i = 0; i < tournamentSize; i++) {
      const random = results[Math.floor(Math.random() * results.length)];
      if (!best || random.fitness > best.fitness) {
        best = random;
      }
    }

    return best;
  }

  /**
   * Crossover two strategies
   */
  crossover(parent1, parent2) {
    const child = {};

    for (const param in parent1) {
      // 50/50 chance to inherit from each parent
      if (Math.random() < 0.5) {
        child[param] = JSON.parse(JSON.stringify(parent1[param]));
      } else {
        child[param] = JSON.parse(JSON.stringify(parent2[param]));
      }
    }

    return child;
  }

  /**
   * Mutate a strategy
   */
  mutate(strategy) {
    // Pick random parameter to mutate
    const params = Object.keys(this.config.parameters);
    const paramToMutate = params[Math.floor(Math.random() * params.length)];
    const range = this.config.parameters[paramToMutate];

    if (typeof range.min === 'number') {
      // Mutate by one step up or down
      const currentValue = strategy[paramToMutate];
      const direction = Math.random() < 0.5 ? -1 : 1;
      const newValue = currentValue + (direction * range.step);

      // Keep within bounds
      strategy[paramToMutate] = Math.max(range.min, Math.min(range.max, newValue));
    }
  }

  /**
   * Calculate max drawdown
   */
  calculateMaxDrawdown(trades) {
    let peak = 10000;
    let maxDrawdown = 0;
    let balance = 10000;

    for (const trade of trades) {
      balance += trade.pnl;
      if (balance > peak) {
        peak = balance;
      }
      const drawdown = (peak - balance) / peak * 100;
      maxDrawdown = Math.max(maxDrawdown, drawdown);
    }

    return maxDrawdown;
  }

  /**
   * Save best strategy to file
   */
  saveBestStrategy() {
    const strategyPath = path.join(
      this.ogzPrime.config.profilesDirectory,
      `optimized_${this.config.optimizeFor}_strategy.json`
    );

    const data = {
      strategy: this.bestStrategy.strategy,
      performance: this.bestStrategy.performance,
      fitness: this.bestStrategy.fitness,
      generation: this.generation,
      timestamp: new Date().toISOString()
    };

    fs.writeFileSync(strategyPath, JSON.stringify(data, null, 2));
    console.log(`ðŸ’¾ Best strategy saved to ${strategyPath}`);
  }

  /**
   * Apply best strategy to live bot
   */
  applyBestStrategy() {
    if (!this.bestStrategy) {
      console.log('âŒ No optimized strategy found!');
      return false;
    }

    console.log('ðŸš€ Applying optimized strategy to live bot...');

    // Update bot configuration
    Object.assign(this.ogzPrime.config, this.bestStrategy.strategy);

    // Save to profile
    this.ogzPrime.saveProfile();

    console.log('âœ… Optimized strategy applied!');
    console.log('Expected performance:', this.bestStrategy.performance);

    return true;
  }
}

module.exports = StrategyOptimizationEngine;

// VoiceFXSystem.js - Visceral audio feedback for trading events
// Makes your bot sound ALIVE with reactive sound effects

class VoiceFXSystem {
  constructor(options = {}) {
    this.enabled = options.enabled !== false;
    this.volume = options.volume || 0.7;

    // Initialize Web Audio API
    this.audioContext = null;
    this.sounds = {};
    this.voices = {
      main: options.voice || 'Alex', // System voice
      rate: options.rate || 1.1,
      pitch: options.pitch || 1.0
    };

    // Sound effect presets
    this.presets = {
      profit: { reverb: 0.3, delay: 0.1, pitch: 1.2, excitement: 0.8 },
      loss: { reverb: 0.1, delay: 0, pitch: 0.8, excitement: 0.3 },
      warning: { reverb: 0.2, delay: 0.05, pitch: 0.9, excitement: 0.6 },
      epic: { reverb: 0.5, delay: 0.2, pitch: 1.1, excitement: 1.0 },
      calm: { reverb: 0.1, delay: 0, pitch: 1.0, excitement: 0.2 }
    };

    this.initialize();
  }

  initialize() {
    if (typeof window !== 'undefined' && window.AudioContext) {
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
      this.setupEffects();
      this.loadSounds();
    }
  }

  setupEffects() {
    // Master gain
    this.masterGain = this.audioContext.createGain();
    this.masterGain.gain.value = this.volume;

    // Reverb (convolver)
    this.convolver = this.audioContext.createConvolver();
    this.reverbGain = this.audioContext.createGain();

    // Delay
    this.delay = this.audioContext.createDelay(1.0);
    this.delayGain = this.audioContext.createGain();

    // Filter for tone shaping
    this.filter = this.audioContext.createBiquadFilter();
    this.filter.type = 'highpass';
    this.filter.frequency.value = 100;

    // Connect effects chain
    this.connectEffects();

    // Create impulse response for reverb
    this.createReverbImpulse();
  }

  connectEffects() {
    // Dry path
    this.filter.connect(this.masterGain);

    // Reverb path
    this.filter.connect(this.convolver);
    this.convolver.connect(this.reverbGain);
    this.reverbGain.connect(this.masterGain);

    // Delay path
    this.filter.connect(this.delay);
    this.delay.connect(this.delayGain);
    this.delayGain.connect(this.masterGain);

    // Feedback loop for delay
    this.delayGain.connect(this.delay);

    // Connect to output
    this.masterGain.connect(this.audioContext.destination);
  }

  createReverbImpulse() {
    const length = this.audioContext.sampleRate * 2; // 2 second reverb
    const impulse = this.audioContext.createBuffer(2, length, this.audioContext.sampleRate);

    for (let channel = 0; channel < 2; channel++) {
      const channelData = impulse.getChannelData(channel);
      for (let i = 0; i < length; i++) {
        channelData[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, 2);
      }
    }

    this.convolver.buffer = impulse;
  }

  /**
   * Load sound effects
   */
  async loadSounds() {
    // Synthesize basic trading sounds
    this.sounds = {
      profit: this.createProfitSound(),
      loss: this.createLossSound(),
      alert: this.createAlertSound(),
      success: this.createSuccessSound(),
      tick: this.createTickSound()
    };
  }

  createProfitSound() {
    return () => {
      const osc = this.audioContext.createOscillator();
      const gain = this.audioContext.createGain();

      osc.connect(gain);
      gain.connect(this.filter);

      // Rising tone for profit
      osc.frequency.setValueAtTime(400, this.audioContext.currentTime);
      osc.frequency.exponentialRampToValueAtTime(800, this.audioContext.currentTime + 0.2);

      gain.gain.setValueAtTime(0.3, this.audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.5);

      osc.start();
      osc.stop(this.audioContext.currentTime + 0.5);
    };
  }

  createLossSound() {
    return () => {
      const osc = this.audioContext.createOscillator();
      const gain = this.audioContext.createGain();

      osc.connect(gain);
      gain.connect(this.filter);

      // Falling tone for loss
      osc.frequency.setValueAtTime(600, this.audioContext.currentTime);
      osc.frequency.exponentialRampToValueAtTime(200, this.audioContext.currentTime + 0.3);

      gain.gain.setValueAtTime(0.2, this.audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.4);

      osc.start();
      osc.stop(this.audioContext.currentTime + 0.4);
    };
  }

  createAlertSound() {
    return () => {
      // Two-tone alert
      [440, 554].forEach((freq, i) => {
        setTimeout(() => {
          const osc = this.audioContext.createOscillator();
          const gain = this.audioContext.createGain();

          osc.connect(gain);
          gain.connect(this.filter);

          osc.frequency.value = freq;
          gain.gain.setValueAtTime(0.2, this.audioContext.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.1);

          osc.start();
          osc.stop(this.audioContext.currentTime + 0.1);
        }, i * 150);
      });
    };
  }

  createSuccessSound() {
    return () => {
      const notes = [523, 659, 784]; // C, E, G
      notes.forEach((freq, i) => {
        setTimeout(() => {
          const osc = this.audioContext.createOscillator();
          const gain = this.audioContext.createGain();

          osc.connect(gain);
          gain.connect(this.filter);

          osc.frequency.value = freq;
          gain.gain.setValueAtTime(0.15, this.audioContext.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.3);

          osc.start();
          osc.stop(this.audioContext.currentTime + 0.3);
        }, i * 100);
      });
    };
  }

  createTickSound() {
    return () => {
      const osc = this.audioContext.createOscillator();
      const gain = this.audioContext.createGain();

      osc.connect(gain);
      gain.connect(this.filter);

      osc.frequency.value = 1000;
      gain.gain.setValueAtTime(0.1, this.audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.02);

      osc.start();
      osc.stop(this.audioContext.currentTime + 0.02);
    };
  }

  /**
   * Speak with effects
   */
  speak(text, preset = 'calm') {
    if (!this.enabled) return;

    const effectSettings = this.presets[preset] || this.presets.calm;

    // Apply effect settings
    this.applyEffects(effectSettings);

    // Use speech synthesis
    if ('speechSynthesis' in window) {
      const utterance = new SpeechSynthesisUtterance(text);

      // Apply voice settings based on preset
      utterance.rate = this.voices.rate * (1 + (effectSettings.excitement - 0.5) * 0.4);
      utterance.pitch = this.voices.pitch * effectSettings.pitch;
      utterance.volume = this.volume;

      // Select voice
      const voices = speechSynthesis.getVoices();
      const selectedVoice = voices.find(v => v.name.includes(this.voices.main)) || voices[0];
      if (selectedVoice) utterance.voice = selectedVoice;

      speechSynthesis.speak(utterance);
    }

    // Play associated sound effect
    this.playEffectForPreset(preset);
  }

  applyEffects(settings) {
    // Set reverb amount
    this.reverbGain.gain.value = settings.reverb || 0.2;

    // Set delay
    this.delay.delayTime.value = settings.delay || 0;
    this.delayGain.gain.value = settings.delay > 0 ? 0.3 : 0;

    // Adjust filter based on excitement
    const filterFreq = 100 + (settings.excitement || 0.5) * 1000;
    this.filter.frequency.value = filterFreq;
  }

  playEffectForPreset(preset) {
    switch(preset) {
      case 'profit':
        this.sounds.profit?.();
        break;
      case 'loss':
        this.sounds.loss?.();
        break;
      case 'warning':
        this.sounds.alert?.();
        break;
      case 'epic':
        this.sounds.success?.();
        break;
      default:
        this.sounds.tick?.();
    }
  }

  /**
   * React to trading events
   */
  onTrade(trade) {
    if (!this.enabled) return;

    const profit = trade.profit || 0;

    if (profit > 5) {
      this.speak(`MASSIVE WIN! Plus ${profit.toFixed(1)} percent!`, 'epic');
    } else if (profit > 2) {
      this.speak(`Nice profit! ${profit.toFixed(1)} percent gain.`, 'profit');
    } else if (profit > 0) {
      this.speak(`Small win. ${profit.toFixed(1)} percent.`, 'calm');
    } else if (profit < -2) {
      this.speak(`Loss alert. Down ${Math.abs(profit).toFixed(1)} percent.`, 'loss');
    } else {
      this.speak(`Minor loss. ${Math.abs(profit).toFixed(1)} percent.`, 'calm');
    }
  }

  onCommandExecuted(command, result) {
    if (!this.enabled) return;

    if (result.success) {
      this.speak(result.message || 'Command executed successfully', 'calm');
    } else {
      this.speak(`Error: ${result.error}`, 'warning');
    }
  }

  onMilestone(type, value) {
    if (!this.enabled) return;

    switch(type) {
      case 'profit_target':
        this.speak(`PROFIT TARGET HIT! ${value} percent achieved!`, 'epic');
        break;
      case 'win_streak':
        this.speak(`${value} wins in a row! You're on fire!`, 'profit');
        break;
      case 'daily_goal':
        this.speak(`Daily goal reached! Time to celebrate!`, 'epic');
        break;
      case 'drawdown_warning':
        this.speak(`Warning: Drawdown at ${value} percent`, 'warning');
        break;
    }
  }

  /**
   * Play sound effect
   */
  playSound(soundName) {
    if (!this.enabled || !this.sounds[soundName]) return;
    this.sounds[soundName]();
  }

  /**
   * Set volume
   */
  setVolume(volume) {
    this.volume = Math.max(0, Math.min(1, volume));
    if (this.masterGain) {
      this.masterGain.gain.value = this.volume;
    }
  }

  /**
   * Toggle effects
   */
  toggle() {
    this.enabled = !this.enabled;
    return this.enabled;
  }
}

