/**
 * COMPRESSED LOG MANAGER
 * 
 * Handles log compression, rotation, and memory management
 * to prevent the self-consuming bots from eating all your RAM/disk
 */

const fs = require('fs').promises;
const path = require('path');
const zlib = require('zlib');
const { promisify } = require('util');

const gzip = promisify(zlib.gzip);
const gunzip = promisify(zlib.gunzip);

class CompressedLogManager {
    constructor(config = {}) {
        this.config = {
            maxLogSize: config.maxLogSize || 10 * 1024 * 1024, // 10MB per file
            maxTotalSize: config.maxTotalSize || 100 * 1024 * 1024, // 100MB total
            compressionLevel: config.compressionLevel || 9, // Max compression
            rotationInterval: config.rotationInterval || 3600000, // Rotate hourly
            retentionDays: config.retentionDays || 7, // Keep 7 days of logs
            compressAfterHours: config.compressAfterHours || 1, // Compress after 1 hour
            ...config
        };

        this.logQueue = [];
        this.currentSize = 0;
        this.isCompressing = false;

        // Start rotation timer
        this.startRotation();

        console.log('ðŸ“¦ COMPRESSED LOG MANAGER INITIALIZED');
        console.log(`   Max size: ${this.config.maxTotalSize / 1024 / 1024}MB`);
        console.log(`   Retention: ${this.config.retentionDays} days`);
    }

    /**
     * Write log entry with automatic compression
     */
    async writeLog(botTier, logType, data) {
        const entry = {
            timestamp: Date.now(),
            botTier,
            type: logType,
            data: this.compressData(data) // Compress data structure
        };

        // Add to queue
        this.logQueue.push(entry);

        // Batch write for efficiency
        if (this.logQueue.length >= 100 || Date.now() - this.lastWrite > 5000) {
            await this.flushQueue();
        }

        // Check size limits
        await this.checkSizeLimits();
    }

    /**
     * Compress data structure (remove redundant fields)
     */
    compressData(data) {
        // Remove redundant/large fields
        const compressed = { ...data };

        // Remove large arrays if they exist
        if (compressed.candles && compressed.candles.length > 50) {
            compressed.candles = compressed.candles.slice(-50); // Keep only last 50
        }

        // Round numbers to save space
        if (compressed.price) compressed.price = Math.round(compressed.price * 100) / 100;
        if (compressed.confidence) compressed.confidence = Math.round(compressed.confidence * 10) / 10;

        // Remove debug fields
        delete compressed.debug;
        delete compressed.raw;
        delete compressed.fullData;

        return compressed;
    }

    /**
     * Flush log queue to disk
     */
    async flushQueue() {
        if (this.logQueue.length === 0) return;

        const logs = [...this.logQueue];
        this.logQueue = [];
        this.lastWrite = Date.now();

        // Group by bot tier
        const grouped = {};
        logs.forEach(log => {
            if (!grouped[log.botTier]) grouped[log.botTier] = [];
            grouped[log.botTier].push(log);
        });

        // Write each tier's logs
        for (const [tier, tierLogs] of Object.entries(grouped)) {
            await this.appendToFile(tier, tierLogs);
        }
    }

    /**
     * Append logs to file with size checking
     */
    async appendToFile(botTier, logs) {
        const date = new Date().toISOString().split('T')[0];
        const hour = new Date().getHours();
        const filename = `${botTier}_${date}_${hour}.json`;
        const filepath = path.join(this.config.logPath, filename);

        try {
            // Check if file exists and its size
            let existingLogs = [];
            let fileSize = 0;

            try {
                const stats = await fs.stat(filepath);
                fileSize = stats.size;

                if (fileSize < this.config.maxLogSize) {
                    const content = await fs.readFile(filepath, 'utf8');
                    existingLogs = JSON.parse(content);
                }
            } catch (e) {
                // File doesn't exist
            }

            // If file too large, rotate
            if (fileSize >= this.config.maxLogSize) {
                await this.rotateFile(filepath);
                existingLogs = [];
            }

            // Append new logs
            existingLogs.push(...logs);

            // Write back
            await fs.writeFile(filepath, JSON.stringify(existingLogs));

            // Update current size
            this.currentSize += JSON.stringify(logs).length;

        } catch (error) {
            console.error(`Error writing logs for ${botTier}:`, error);
        }
    }

    /**
     * Rotate and compress old file
     */
    async rotateFile(filepath) {
        const compressed = `${filepath}.gz`;

        try {
            // Read file
            const content = await fs.readFile(filepath);

            // Compress with max compression
            const compressedContent = await gzip(content, {
                level: this.config.compressionLevel
            });

            // Write compressed file
            await fs.writeFile(compressed, compressedContent);

            // Delete original
            await fs.unlink(filepath);

            console.log(`ðŸ—œï¸ Compressed ${path.basename(filepath)} (${content.length} â†’ ${compressedContent.length} bytes)`);

        } catch (error) {
            console.error('Error rotating file:', error);
        }
    }

    /**
     * Read compressed logs for consumption
     */
    async readLogs(botTier, startTime = null, endTime = null) {
        const logs = [];

        try {
            const files = await fs.readdir(this.config.logPath);
            const tierFiles = files.filter(f => f.startsWith(botTier));

            for (const file of tierFiles) {
                const filepath = path.join(this.config.logPath, file);

                if (file.endsWith('.gz')) {
                    // Read compressed file
                    const compressed = await fs.readFile(filepath);
                    const decompressed = await gunzip(compressed);
                    const fileLogs = JSON.parse(decompressed.toString());

                    // Filter by time if needed
                    if (startTime || endTime) {
                        logs.push(...fileLogs.filter(log => {
                            if (startTime && log.timestamp < startTime) return false;
                            if (endTime && log.timestamp > endTime) return false;
                            return true;
                        }));
                    } else {
                        logs.push(...fileLogs);
                    }
                } else if (file.endsWith('.json')) {
                    // Read uncompressed file
                    const content = await fs.readFile(filepath, 'utf8');
                    const fileLogs = JSON.parse(content);
                    logs.push(...fileLogs);
                }
            }
        } catch (error) {
            console.error('Error reading logs:', error);
        }

        return logs;
    }

    /**
     * Check and enforce size limits
     */
    async checkSizeLimits() {
        if (this.isCompressing) return;

        try {
            const files = await fs.readdir(this.config.logPath);
            let totalSize = 0;
            const fileStats = [];

            // Get all file sizes
            for (const file of files) {
                const filepath = path.join(this.config.logPath, file);
                const stats = await fs.stat(filepath);
                totalSize += stats.size;
                fileStats.push({ file, size: stats.size, mtime: stats.mtime });
            }

            // If over limit, delete oldest files
            if (totalSize > this.config.maxTotalSize) {
                console.log(`âš ï¸ Log size limit exceeded: ${(totalSize / 1024 / 1024).toFixed(2)}MB`);

                this.isCompressing = true;

                // Sort by modification time (oldest first)
                fileStats.sort((a, b) => a.mtime - b.mtime);

                // Delete oldest files until under limit
                while (totalSize > this.config.maxTotalSize && fileStats.length > 0) {
                    const oldest = fileStats.shift();
                    const filepath = path.join(this.config.logPath, oldest.file);

                    await fs.unlink(filepath);
                    totalSize -= oldest.size;

                    console.log(`ðŸ—‘ï¸ Deleted old log: ${oldest.file}`);
                }

                this.isCompressing = false;
            }

            // Compress old uncompressed files
            await this.compressOldFiles();

        } catch (error) {
            console.error('Error checking size limits:', error);
            this.isCompressing = false;
        }
    }

    /**
     * Compress files older than threshold
     */
    async compressOldFiles() {
        const now = Date.now();
        const threshold = this.config.compressAfterHours * 60 * 60 * 1000;

        try {
            const files = await fs.readdir(this.config.logPath);

            for (const file of files) {
                if (!file.endsWith('.json')) continue;

                const filepath = path.join(this.config.logPath, file);
                const stats = await fs.stat(filepath);

                if (now - stats.mtimeMs > threshold) {
                    await this.rotateFile(filepath);
                }
            }
        } catch (error) {
            console.error('Error compressing old files:', error);
        }
    }

    /**
     * Clean up old logs based on retention policy
     */
    async cleanupOldLogs() {
        const now = Date.now();
        const retentionMs = this.config.retentionDays * 24 * 60 * 60 * 1000;

        try {
            const files = await fs.readdir(this.config.logPath);

            for (const file of files) {
                const filepath = path.join(this.config.logPath, file);
                const stats = await fs.stat(filepath);

                if (now - stats.mtimeMs > retentionMs) {
                    await fs.unlink(filepath);
                    console.log(`ðŸ—‘ï¸ Cleaned up old log: ${file}`);
                }
            }
        } catch (error) {
            console.error('Error cleaning up old logs:', error);
        }
    }

    /**
     * Start automatic rotation and cleanup
     */
    startRotation() {
        // Rotate logs hourly
        setInterval(() => {
            this.flushQueue();
            this.checkSizeLimits();
        }, this.config.rotationInterval);

        // Clean up daily
        setInterval(() => {
            this.cleanupOldLogs();
        }, 24 * 60 * 60 * 1000);
    }

    /**
     * Get storage statistics
     */
    async getStats() {
        const files = await fs.readdir(this.config.logPath);
        let totalSize = 0;
        let compressedFiles = 0;
        let uncompressedFiles = 0;

        for (const file of files) {
            const filepath = path.join(this.config.logPath, file);
            const stats = await fs.stat(filepath);
            totalSize += stats.size;

            if (file.endsWith('.gz')) {
                compressedFiles++;
            } else {
                uncompressedFiles++;
            }
        }

        return {
            totalSize: `${(totalSize / 1024 / 1024).toFixed(2)}MB`,
            totalFiles: files.length,
            compressedFiles,
            uncompressedFiles,
            utilizationPercent: ((totalSize / this.config.maxTotalSize) * 100).toFixed(1) + '%'
        };
    }
}

module.exports = CompressedLogManager;

// VoiceFXSystem.js - Visceral audio feedback for trading events
// Makes your bot sound ALIVE with reactive sound effects

class VoiceFXSystem {
  constructor(options = {}) {
    this.enabled = options.enabled !== false;
    this.volume = options.volume || 0.7;

    // Initialize Web Audio API
    this.audioContext = null;
    this.sounds = {};
    this.voices = {
      main: options.voice || 'Alex', // System voice
      rate: options.rate || 1.1,
      pitch: options.pitch || 1.0
    };

    // Sound effect presets
    this.presets = {
      profit: { reverb: 0.3, delay: 0.1, pitch: 1.2, excitement: 0.8 },
      loss: { reverb: 0.1, delay: 0, pitch: 0.8, excitement: 0.3 },
      warning: { reverb: 0.2, delay: 0.05, pitch: 0.9, excitement: 0.6 },
      epic: { reverb: 0.5, delay: 0.2, pitch: 1.1, excitement: 1.0 },
      calm: { reverb: 0.1, delay: 0, pitch: 1.0, excitement: 0.2 }
    };

    this.initialize();
  }

  initialize() {
    if (typeof window !== 'undefined' && window.AudioContext) {
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
      this.setupEffects();
      this.loadSounds();
    }
  }

  setupEffects() {
    // Master gain
    this.masterGain = this.audioContext.createGain();
    this.masterGain.gain.value = this.volume;

    // Reverb (convolver)
    this.convolver = this.audioContext.createConvolver();
    this.reverbGain = this.audioContext.createGain();

    // Delay
    this.delay = this.audioContext.createDelay(1.0);
    this.delayGain = this.audioContext.createGain();

    // Filter for tone shaping
    this.filter = this.audioContext.createBiquadFilter();
    this.filter.type = 'highpass';
    this.filter.frequency.value = 100;

    // Connect effects chain
    this.connectEffects();

    // Create impulse response for reverb
    this.createReverbImpulse();
  }

  connectEffects() {
    // Dry path
    this.filter.connect(this.masterGain);

    // Reverb path
    this.filter.connect(this.convolver);
    this.convolver.connect(this.reverbGain);
    this.reverbGain.connect(this.masterGain);

    // Delay path
    this.filter.connect(this.delay);
    this.delay.connect(this.delayGain);
    this.delayGain.connect(this.masterGain);

    // Feedback loop for delay
    this.delayGain.connect(this.delay);

    // Connect to output
    this.masterGain.connect(this.audioContext.destination);
  }

  createReverbImpulse() {
    const length = this.audioContext.sampleRate * 2; // 2 second reverb
    const impulse = this.audioContext.createBuffer(2, length, this.audioContext.sampleRate);

    for (let channel = 0; channel < 2; channel++) {
      const channelData = impulse.getChannelData(channel);
      for (let i = 0; i < length; i++) {
        channelData[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, 2);
      }
    }

    this.convolver.buffer = impulse;
  }

  /**
   * Load sound effects
   */
  async loadSounds() {
    // Synthesize basic trading sounds
    this.sounds = {
      profit: this.createProfitSound(),
      loss: this.createLossSound(),
      alert: this.createAlertSound(),
      success: this.createSuccessSound(),
      tick: this.createTickSound()
    };
  }

  createProfitSound() {
    return () => {
      const osc = this.audioContext.createOscillator();
      const gain = this.audioContext.createGain();

      osc.connect(gain);
      gain.connect(this.filter);

      // Rising tone for profit
      osc.frequency.setValueAtTime(400, this.audioContext.currentTime);
      osc.frequency.exponentialRampToValueAtTime(800, this.audioContext.currentTime + 0.2);

      gain.gain.setValueAtTime(0.3, this.audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.5);

      osc.start();
      osc.stop(this.audioContext.currentTime + 0.5);
    };
  }

  createLossSound() {
    return () => {
      const osc = this.audioContext.createOscillator();
      const gain = this.audioContext.createGain();

      osc.connect(gain);
      gain.connect(this.filter);

      // Falling tone for loss
      osc.frequency.setValueAtTime(600, this.audioContext.currentTime);
      osc.frequency.exponentialRampToValueAtTime(200, this.audioContext.currentTime + 0.3);

      gain.gain.setValueAtTime(0.2, this.audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.4);

      osc.start();
      osc.stop(this.audioContext.currentTime + 0.4);
    };
  }

  createAlertSound() {
    return () => {
      // Two-tone alert
      [440, 554].forEach((freq, i) => {
        setTimeout(() => {
          const osc = this.audioContext.createOscillator();
          const gain = this.audioContext.createGain();

          osc.connect(gain);
          gain.connect(this.filter);

          osc.frequency.value = freq;
          gain.gain.setValueAtTime(0.2, this.audioContext.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.1);

          osc.start();
          osc.stop(this.audioContext.currentTime + 0.1);
        }, i * 150);
      });
    };
  }

  createSuccessSound() {
    return () => {
      const notes = [523, 659, 784]; // C, E, G
      notes.forEach((freq, i) => {
        setTimeout(() => {
          const osc = this.audioContext.createOscillator();
          const gain = this.audioContext.createGain();

          osc.connect(gain);
          gain.connect(this.filter);

          osc.frequency.value = freq;
          gain.gain.setValueAtTime(0.15, this.audioContext.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.3);

          osc.start();
          osc.stop(this.audioContext.currentTime + 0.3);
        }, i * 100);
      });
    };
  }

  createTickSound() {
    return () => {
      const osc = this.audioContext.createOscillator();
      const gain = this.audioContext.createGain();

      osc.connect(gain);
      gain.connect(this.filter);

      osc.frequency.value = 1000;
      gain.gain.setValueAtTime(0.1, this.audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.02);

      osc.start();
      osc.stop(this.audioContext.currentTime + 0.02);
    };
  }

  /**
   * Speak with effects
   */
  speak(text, preset = 'calm') {
    if (!this.enabled) return;

    const effectSettings = this.presets[preset] || this.presets.calm;

    // Apply effect settings
    this.applyEffects(effectSettings);

    // Use speech synthesis
    if ('speechSynthesis' in window) {
      const utterance = new SpeechSynthesisUtterance(text);

      // Apply voice settings based on preset
      utterance.rate = this.voices.rate * (1 + (effectSettings.excitement - 0.5) * 0.4);
      utterance.pitch = this.voices.pitch * effectSettings.pitch;
      utterance.volume = this.volume;

      // Select voice
      const voices = speechSynthesis.getVoices();
      const selectedVoice = voices.find(v => v.name.includes(this.voices.main)) || voices[0];
      if (selectedVoice) utterance.voice = selectedVoice;

      speechSynthesis.speak(utterance);
    }

    // Play associated sound effect
    this.playEffectForPreset(preset);
  }

  applyEffects(settings) {
    // Set reverb amount
    this.reverbGain.gain.value = settings.reverb || 0.2;

    // Set delay
    this.delay.delayTime.value = settings.delay || 0;
    this.delayGain.gain.value = settings.delay > 0 ? 0.3 : 0;

    // Adjust filter based on excitement
    const filterFreq = 100 + (settings.excitement || 0.5) * 1000;
    this.filter.frequency.value = filterFreq;
  }

  playEffectForPreset(preset) {
    switch(preset) {
      case 'profit':
        this.sounds.profit?.();
        break;
      case 'loss':
        this.sounds.loss?.();
        break;
      case 'warning':
        this.sounds.alert?.();
        break;
      case 'epic':
        this.sounds.success?.();
        break;
      default:
        this.sounds.tick?.();
    }
  }

  /**
   * React to trading events
   */
  onTrade(trade) {
    if (!this.enabled) return;

    const profit = trade.profit || 0;

    if (profit > 5) {
      this.speak(`MASSIVE WIN! Plus ${profit.toFixed(1)} percent!`, 'epic');
    } else if (profit > 2) {
      this.speak(`Nice profit! ${profit.toFixed(1)} percent gain.`, 'profit');
    } else if (profit > 0) {
      this.speak(`Small win. ${profit.toFixed(1)} percent.`, 'calm');
    } else if (profit < -2) {
      this.speak(`Loss alert. Down ${Math.abs(profit).toFixed(1)} percent.`, 'loss');
    } else {
      this.speak(`Minor loss. ${Math.abs(profit).toFixed(1)} percent.`, 'calm');
    }
  }

  onCommandExecuted(command, result) {
    if (!this.enabled) return;

    if (result.success) {
      this.speak(result.message || 'Command executed successfully', 'calm');
    } else {
      this.speak(`Error: ${result.error}`, 'warning');
    }
  }

  onMilestone(type, value) {
    if (!this.enabled) return;

    switch(type) {
      case 'profit_target':
        this.speak(`PROFIT TARGET HIT! ${value} percent achieved!`, 'epic');
        break;
      case 'win_streak':
        this.speak(`${value} wins in a row! You're on fire!`, 'profit');
        break;
      case 'daily_goal':
        this.speak(`Daily goal reached! Time to celebrate!`, 'epic');
        break;
      case 'drawdown_warning':
        this.speak(`Warning: Drawdown at ${value} percent`, 'warning');
        break;
    }
  }

  /**
   * Play sound effect
   */
  playSound(soundName) {
    if (!this.enabled || !this.sounds[soundName]) return;
    this.sounds[soundName]();
  }

  /**
   * Set volume
   */
  setVolume(volume) {
    this.volume = Math.max(0, Math.min(1, volume));
    if (this.masterGain) {
      this.masterGain.gain.value = this.volume;
    }
  }

  /**
   * Toggle effects
   */
  toggle() {
    this.enabled = !this.enabled;
    return this.enabled;
  }
}

