    // Check consecutive losses
    if (this.state.consecutiveLosses >= this.config.safetyLimits.maxConsecutiveLosses) {
      console.log(`ðŸ›¡ï¸ SAFETY BLOCK: Too many consecutive losses (${this.state.consecutiveLosses})`);
      return false;
    }

    // Check daily loss limit
    if (this.state.dailyLoss >= this.config.safetyLimits.maxDailyLoss) {
      console.log(`ðŸ›¡ï¸ SAFETY BLOCK: Daily loss limit reached (${(this.state.dailyLoss * 100).toFixed(1)}%)`);
      return false;
    }

    // Check minimum time between trades
    if (this.state.lastTradeTime &&
        currentTime - this.state.lastTradeTime < this.config.safetyLimits.minTimeBetweenTrades) {
      console.log(`ðŸ›¡ï¸ SAFETY BLOCK: Minimum time between trades not met`);
      return false;
