// Generate detailed tax reports (CSV, PDF, 8949) for accountants.

const fs = require('fs');
const path = require('path');
const PDFDocument = require('pdfkit');
const { createObjectCsvWriter: createCsv } = require('csv-writer');

class TaxReportGenerator {
  constructor(config = {}) {
    this.config = {
      outputDir: path.join(process.cwd(), 'output', 'tax'),
      ...config
    };
  }

  async generateAnnualReport(year, trades) {
    const processed = this.processTrades(trades);
    const summary = this.calculateSummary(processed);
    const timestamp = new Date().toISOString().split('T')[0];
    const base = `OGZ_TaxReport_${year}_${timestamp}`;
    await this.generateCSV(processed, `${base}.csv`);
    await this.generatePDF(processed, summary, year, `${base}.pdf`);
    await this.generate8949Format(processed, `${base}_8949.csv`);
    console.log('âœ… Tax reports generated in', this.config.outputDir);
  }

  processTrades(trades) {
    return trades.map(t => {
      const holdDays = (new Date(t.exitTime) - new Date(t.entryTime))/(1000*60*60*24);
      return {
        asset: t.assetName || 'BTC-USD',
        entryDate: new Date(t.entryTime).toISOString().split('T')[0],
        exitDate: new Date(t.exitTime).toISOString().split('T')[0],
        proceeds: t.exitPrice * t.size,
        costBasis: t.entryPrice * t.size,
        gainLoss: t.pnl,
        isLongTerm: holdDays>365,
        holdTimeDays: Math.floor(holdDays),
      };
    });
  }

  calculateSummary(processed) {
    return processed.reduce((sum, t) => {
      sum.totalTrades++;
      sum[t.isLongTerm?'longTermTrades':'shortTermTrades']++;
      sum.totalGains += Math.max(0, t.gainLoss);
      sum.totalLosses += Math.max(0, -t.gainLoss);
      return sum;
    }, { totalTrades:0, shortTermTrades:0, longTermTrades:0, totalGains:0, totalLosses:0 });
  }

  async generateCSV(records, filename) {
    const writer = createCsv({ path:path.join(this.config.outputDir, filename), header:Object.keys(records[0]).map(f=>({id:f,title:f})) });
    await writer.writeRecords(records);
    console.log('ðŸ“„ CSV saved:', filename);
  }

  async generate8949Format(records, filename) {
    // Format same fields into IRS 8949 formatâ€¦
  }

  async generatePDF(records, summary, year, filename) {
    const doc = new PDFDocument();
    doc.pipe(fs.createWriteStream(path.join(this.config.outputDir, filename)));
    doc.fontSize(24).text(`Tax Report ${year}`, { align:'center' }).moveDown();
    doc.fontSize(12).text(JSON.stringify(summary, null, 2));
    doc.end();
    console.log('ðŸ“‹ PDF saved:', filename);
  }
}

module.exports = TaxReportGenerator;

import React, { useState, useEffect } from 'react';

// HitchQuickFire - Instant replay profitable commands during hot sessions
const HitchQuickFire = ({ ogzPrime, position = 'bottom-right' }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [quickCommands, setQuickCommands] = useState([]);
  const [executing, setExecuting] = useState(null);
  const [sessionStats, setSessionStats] = useState({ profit: 0, trades: 0 });

  const hitchLogger = ogzPrime?.hitch?.logger;
  const hitch = ogzPrime?.hitch;

  // Load top profitable commands for quick access
  useEffect(() => {
    if (!hitchLogger) return;

    const loadQuickCommands = async () => {
      const history = await hitchLogger.getCommandHistory({
        startDate: Date.now() - (7 * 24 * 60 * 60 * 1000) // Last 7 days
      });

      // Get top 5 most profitable commands
      const profitable = history
        .filter(cmd => {
          if (!cmd.impact?.updates?.length) return false;
          const finalUpdate = cmd.impact.updates[cmd.impact.updates.length - 1];
          return finalUpdate.percentChange > 1; // Only 1%+ winners
        })
        .sort((a, b) => {
          const aProfit = a.impact.updates[a.impact.updates.length - 1].percentChange;
          const bProfit = b.impact.updates[b.impact.updates.length - 1].percentChange;
          return bProfit - aProfit;
        })
        .slice(0, 5)
        .map(cmd => ({
          id: cmd.id,
          command: cmd.input,
          profit: cmd.impact.updates[cmd.impact.updates.length - 1].percentChange,
          icon: getCommandIcon(cmd.input),
          shortName: getShortName(cmd.input)
        }));

      setQuickCommands(profitable);
    };

    loadQuickCommands();
    // Refresh every minute
    const interval = setInterval(loadQuickCommands, 60000);
    return () => clearInterval(interval);
  }, [hitchLogger]);

  // Get icon based on command type
  const getCommandIcon = (command) => {
    const lower = command.toLowerCase();
    if (lower.includes('risk')) return 'âš–ï¸';
    if (lower.includes('stop')) return 'ðŸ›‘';
    if (lower.includes('start')) return 'â–¶ï¸';
    if (lower.includes('profile')) return 'ðŸ‘¤';
    if (lower.includes('rsi') || lower.includes('macd')) return 'ðŸ“Š';
    if (lower.includes('time') || lower.includes('after') || lower.includes('before')) return 'â°';
    return 'ðŸŽ¯';
  };

  // Get short name for button
  const getShortName = (command) => {
    const lower = command.toLowerCase();
    if (lower.includes('risk')) return 'Risk';
    if (lower.includes('stop trading')) return 'Stop';
    if (lower.includes('start trading')) return 'Start';
    if (lower.includes('scalper')) return 'Scalper';
    if (lower.includes('conservative')) return 'Safe';
    if (lower.includes('aggressive')) return 'Aggro';
    if (lower.includes('rsi')) return 'RSI';
    // Take first two words
    return command.split(' ').slice(0, 2).join(' ');
  };

  // Execute command instantly
  const fireCommand = async (cmd) => {
    if (!hitch || executing) return;

    setExecuting(cmd.id);

    try {
      const result = await hitch.processCommand(cmd.command, {
        source: 'quickfire',
        timestamp: Date.now()
      });

      if (result.success) {
        // Flash success
        showToast(`ðŸš€ ${cmd.shortName} FIRED!`, 'success');

        // Update session stats
        setSessionStats(prev => ({
          profit: prev.profit + (cmd.profit || 0),
          trades: prev.trades + 1
        }));
      } else {
        showToast(`âŒ ${result.error}`, 'error');
      }
    } catch (error) {
      showToast(`âŒ Failed: ${error.message}`, 'error');
    } finally {
      setTimeout(() => setExecuting(null), 500);
    }
  };

  // Toast notification
  const showToast = (message, type) => {
    const toast = document.createElement('div');
    toast.style.cssText = `
      position: fixed;
      top: 20px;
      right: 20px;
      padding: 15px 25px;
      background: ${type === 'success' ? '#00ff00' : '#ff0000'};
      color: #000;
      font-weight: bold;
