    const p = amplitudeResult.amplitude;
    const q = 1 - p;
    const b = 1; // 1:1 odds assumption

    const kellyFraction = (p * b - q) / b;
    return Math.max(0, Math.min(0.25, kellyFraction)) * maxCapital; // Max 25% Kelly
