    if (avgSharpe > 2.0) {
      this.voice.speak('Quantum optimization achieving exceptional performance. Sharpe ratio exceeding 2.0.');
    }
  }

  // Utility functions
  calculateExpectedReturn(historicalData) {
    const returns = this.calculateDailyReturns(historicalData);
    if (returns.length === 0) return 0;

    const avgReturn = returns.reduce((a, b) => a + b, 0) / returns.length;
    return avgReturn * 252; // Annualized
  }

  calculateDailyReturns(historicalData) {
    const returns = [];
    for (let i = 1; i < historicalData.length; i++) {
      const return_ = (historicalData[i].close - historicalData[i-1].close) / historicalData[i-1].close;
      returns.push(return_);
    }
    return returns;
  }

  calculateVolatility(historicalData) {
    const returns = this.calculateDailyReturns(historicalData);
    if (returns.length === 0) return 0.01;

    const mean = returns.reduce((a, b) => a + b, 0) / returns.length;
    const variance = returns.reduce((sum, r) => sum + Math.pow(r - mean, 2), 0) / returns.length;

    return Math.sqrt(variance) * Math.sqrt(252); // Annualized volatility
  }

  calculateMomentum(historicalData) {
    if (historicalData.length < 2) return 0;

    const recent = historicalData[historicalData.length - 1].close;
    const past = historicalData[0].close;

    return (recent - past) / past;
  }

  calculateTrend(historicalData) {
    // Simple linear regression slope
    const n = historicalData.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;

    for (let i = 0; i < n; i++) {
      sumX += i;
      sumY += historicalData[i].close;
      sumXY += i * historicalData[i].close;
      sumX2 += i * i;
    }

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    return slope;
  }

