                  fontWeight: 'bold',
                  textShadow: cmd.percentChange >= 5 ? '0 0 5px currentColor' : 'none'
                }}>
                  {cmd.percentChange >= 0 ? '+' : ''}{cmd.percentChange.toFixed(2)}%
