                    disabled={replayingId === cmd.id}
                    onMouseEnter={(e) => {
                      if (replayingId !== cmd.id) {
                        e.target.style.backgroundColor = '#00ff00';
                        e.target.style.color = '#000';
                      }
                    }}
                    onMouseLeave={(e) => {
                      if (replayingId !== cmd.id) {
