                        e.target.style.color = '#00ff00';
                      }
                    }}
                  >
                    {replayingId === cmd.id ? 'REPLAYING...' : 'REPLAY'}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <style>
        {`
          @keyframes pulse {
            0% { opacity: 1; }
            50% { opacity: 0.5; }
            100% { opacity: 1; }
          }
        `}
      </style>
    </div>
  );
};

