        volatilityRegime: this.riskState.volatilityRegime,
        tradesAnalyzed: this.tradeHistory.length
      }
    };
  }

  calculateSharpeRatio() {
    if (this.tradeHistory.length === 0) return 0;

    const returns = this.tradeHistory.map(t => t.profit);
    const avgReturn = returns.reduce((a, b) => a + b, 0) / returns.length;

    const variance = returns.reduce((sum, r) => sum + Math.pow(r - avgReturn, 2), 0) / returns.length;
    const stdDev = Math.sqrt(variance);

    if (stdDev === 0) return 0;

    const riskFreeRate = 0.02 / 365; // Daily risk-free rate
    return (avgReturn - riskFreeRate) / stdDev;
  }
}

