                // Check if running locally or on VPS
                const isLocal = window.location.hostname === 'localhost' || 
                               window.location.hostname === '127.0.0.1' ||
                               window.location.hostname === '';

                // VPS IP from your configuration
                const VPS_IP = '149.28.242.111';

                if (isLocal) {
                    return `ws://127.0.0.1:${wsPort}/ws`;
                } else if (window.location.hostname === VPS_IP) {
                    // Direct VPS connection
                    return `ws://${VPS_IP}:${wsPort}/ws`;
                } else {
                    // Production with domain
                    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
                    return `${protocol}//${window.location.hostname}:${wsPort}/ws`;
                }
            }

            init() {
