```javascript
// Use Worker Threads for parallel processing
import { Worker } from 'worker_threads';

class ParallelOGZProcessor {
    constructor() {
        this.ganWorker = new Worker('./workers/gan_worker.js');
        this.gannWorker = new Worker('./workers/gann_worker.js');
    }

    async processInParallel(marketData) {
        const [ganSignal, gannSignal] = await Promise.all([
            this.runGANWorker(marketData),
            this.runGANNWorker(marketData)
        ]);

        return this.combineSignals(ganSignal, gannSignal);
    }

    runGANWorker(data) {
        return new Promise((resolve) => {
            this.ganWorker.postMessage({ type: 'PROCESS', data });
            this.ganWorker.once('message', resolve);
        });
    }
}
