  /**
   * Create QUBO for portfolio optimization
   * This is the secret sauce hedge funds pay for!
   */
  createPortfolioQUBO(assets, constraints) {
    const n = assets.length;
    const Q = {};

    // Expected returns (linear terms)
    for (let i = 0; i < n; i++) {
      const key = `${i},${i}`;
      Q[key] = -assets[i].expectedReturn * constraints.returnWeight;
    }

    // Risk (quadratic terms from covariance)
    for (let i = 0; i < n; i++) {
      for (let j = i; j < n; j++) {
        const key = i === j ? `${i},${i}` : `${i},${j}`;
        const covariance = this.getCovariance(assets[i], assets[j]);

        if (Q[key]) {
          Q[key] += covariance * constraints.riskWeight;
        } else {
          Q[key] = covariance * constraints.riskWeight;
        }
      }
    }

    // Budget constraint (must sum to 1)
    const penalty = constraints.budgetPenalty || 100;
    for (let i = 0; i < n; i++) {
      for (let j = i; j < n; j++) {
        const key = i === j ? `${i},${i}` : `${i},${j}`;
        Q[key] = (Q[key] || 0) + penalty * (i === j ? 1 - 2 : 2);
      }
    }

    return { Q, num_variables: n };
  }

  /**
   * Run QAOA on quantum hardware
   */
  async runQAOA(qubo) {
    const depth = 3; // QAOA depth
    const { Q, num_variables } = qubo;

    // Create quantum circuit
    const qreg = new QuantumRegister(num_variables);
    const creg = new ClassicalRegister(num_variables);
    const circuit = new QuantumCircuit(qreg, creg);

    // Initial superposition
    for (let i = 0; i < num_variables; i++) {
      circuit.h(qreg[i]);
    }

    // QAOA layers
    for (let layer = 0; layer < depth; layer++) {
      // Problem Hamiltonian
      await this.applyProblemHamiltonian(circuit, qreg, Q);

      // Mixer Hamiltonian
      await this.applyMixerHamiltonian(circuit, qreg);
    }

    // Measure
    circuit.measure(qreg, creg);

    // Execute on quantum backend
    const job = await this.quantumBackend.run(circuit, { shots: this.config.shots });
    const result = await job.result();

    return {
      counts: result.getCounts(),
      probability: this.extractBestSolution(result),
      executionTime: job.executionTime
    };
  }

