      // Load initial doctrine
      if (process.env.INITIAL_DOCTRINE) {
        await this.moverCore.loadDoctrine(process.env.INITIAL_DOCTRINE);
        await this.moverMemory.ingestDoctrine(
          process.env.INITIAL_DOCTRINE, 
