      trendMediumPeriod: 50,
      trendLongPeriod: 200,

      // Timeframe-specific multipliers
      timeframeMultipliers: {
        '1m': { fib: 50, sr: 100, trend: 20 },
        '5m': { fib: 100, sr: 200, trend: 50 },
        '15m': { fib: 150, sr: 300, trend: 100 },
        '1h': { fib: 200, sr: 500, trend: 200 },
        '4h': { fib: 300, sr: 1000, trend: 500 },
        '1d': { fib: 500, sr: 2000, trend: 1000 }
      }
    };

    // Storage for calculated levels
    this.entryAnalysis = {
      entryPrice: 0,
      entryTime: null,
      timeframe: '5m',
      fibonacciLevels: {},
      supportLevels: [],
      resistanceLevels: [],
      trendAnalysis: {},
      keyLevels: [],
      priceTargets: {},
      stopLevels: {}
    };

    // Hook into trade entry
    this.hookIntoTradeEntry();

    console.log('📊 Dynamic Entry Analysis System Initialized');
  }

  /**
   * HOOK INTO YOUR TRADING BRAIN'S ENTRY SYSTEM
   */
  hookIntoTradeEntry() {
    // Store original openPosition method
    const originalOpen = this.ogz.tradingBrain.openPosition?.bind(this.ogz.tradingBrain);

    if (originalOpen) {
      // Override with our enhanced version
      this.ogz.tradingBrain.openPosition = (type, price, size, reason, confidence) => {
        console.log(`\n🎯 TRADE ENTRY DETECTED - CALCULATING DYNAMIC LEVELS...`);

        // Call original to open position
        const result = originalOpen(type, price, size, reason, confidence);

        // Now calculate all technical levels relative to entry
        this.calculateEntryLevels(type, price);

        return result;
      };
    }

    // Also hook into processAnalysis for real-time updates
    const originalProcess = this.ogz.tradingBrain.processAnalysis?.bind(this.ogz.tradingBrain);

    if (originalProcess) {
      this.ogz.tradingBrain.processAnalysis = (analysis, price) => {
        // If we're about to enter a trade
        if (!this.ogz.tradingBrain.isInPosition() && 
            (analysis.decision === 'buy' || analysis.decision === 'sell')) {

          // Pre-calculate levels for this potential entry
          this.preCalculateLevels(analysis.decision, price);
        }

        return originalProcess(analysis, price);
      };
    }
  }

  /**
   * MAIN CALCULATION METHOD - Called on trade entry
   */
  calculateEntryLevels(direction, entryPrice) {
    const timeframe = this.ogz.config.primaryTimeframe || '5m';
    const candles = this.ogz.timeframeData[timeframe]?.candles;

    if (!candles || candles.length < 50) {
      console.warn('Not enough candles for analysis');
      return;
    }

    // Store entry data
    this.entryAnalysis = {
      entryPrice,
      entryTime: Date.now(),
      direction,
      timeframe,
      fibonacciLevels: {},
      supportLevels: [],
      resistanceLevels: [],
      trendAnalysis: {},
      keyLevels: [],
      priceTargets: {},
      stopLevels: {}
    };

    // Calculate everything relative to entry
    this.calculateDynamicFibonacci(candles, entryPrice, direction);
    this.calculateDynamicSupportResistance(candles, entryPrice);
    this.calculateDynamicTrends(candles, entryPrice);
    this.calculatePriceTargets(direction, entryPrice);
    this.identifyKeyLevels(entryPrice);

    // Broadcast to dashboard
    this.broadcastLevels();

    // Log summary
    this.logEntrySummary();
  }

  /**
   * DYNAMIC FIBONACCI CALCULATION
   * Calculates Fibonacci levels from entry point
   */
  calculateDynamicFibonacci(candles, entryPrice, direction) {
    // Get lookback period based on timeframe
    const multiplier = this.config.timeframeMultipliers[this.entryAnalysis.timeframe];
    const lookback = multiplier ? multiplier.fib : this.config.fibLookback;

    // Find swing high and low before entry
    const recentCandles = candles.slice(-lookback);
    let swingHigh = Math.max(...recentCandles.map(c => c.high));
    let swingLow = Math.min(...recentCandles.map(c => c.low));

    // Find the most recent significant swing points
    const significantSwings = this.findSignificantSwings(recentCandles);
    if (significantSwings.high) swingHigh = significantSwings.high;
    if (significantSwings.low) swingLow = significantSwings.low;

    const range = swingHigh - swingLow;

    // Calculate Fibonacci levels
    this.config.fibLevels.forEach(level => {
      const price = direction === 'buy' 
        ? swingLow + (range * level)  // For longs, measure from low
        : swingHigh - (range * level); // For shorts, measure from high

      this.entryAnalysis.fibonacciLevels[level] = {
        price: price,
        distance: Math.abs(price - entryPrice),
        percentFromEntry: ((price - entryPrice) / entryPrice * 100).toFixed(2),
        type: this.getFibType(level)
      };
    });

    // Special golden zone (0.618 - 0.65)
    this.entryAnalysis.goldenZone = {
      upper: this.entryAnalysis.fibonacciLevels[0.618].price,
      lower: this.entryAnalysis.fibonacciLevels[0.65]?.price || this.entryAnalysis.fibonacciLevels[0.618].price,
      isNearEntry: Math.abs(this.entryAnalysis.fibonacciLevels[0.618].price - entryPrice) / entryPrice < 0.02
    };

    console.log(`📐 Fibonacci levels calculated from entry $${entryPrice.toFixed(2)}`);
    console.log(`   Swing High: $${swingHigh.toFixed(2)}, Swing Low: $${swingLow.toFixed(2)}`);
    console.log(`   Golden Zone: $${this.entryAnalysis.goldenZone.lower?.toFixed(2)} - $${this.entryAnalysis.goldenZone.upper.toFixed(2)}`);
  }

  /**
   * DYNAMIC SUPPORT/RESISTANCE CALCULATION
   */
  calculateDynamicSupportResistance(candles, entryPrice) {
    const multiplier = this.config.timeframeMultipliers[this.entryAnalysis.timeframe];
    const lookback = multiplier ? multiplier.sr : this.config.srLookback;

    const recentCandles = candles.slice(-lookback);
    const levels = new Map();

    // Find price levels with multiple touches
    recentCandles.forEach(candle => {
      // Check highs and lows
      [candle.high, candle.low, candle.close].forEach(price => {
        // Round to nearest significant level
        const roundedPrice = Math.round(price / 10) * 10;

        // Check if any existing level is close
        let found = false;
        levels.forEach((count, level) => {
          if (Math.abs(level - price) / level < this.config.srTolerance) {
            levels.set(level, count + 1);
            found = true;
          }
        });

        if (!found) {
          levels.set(price, 1);
        }
      });
    });

    // Filter for significant levels (multiple touches)
    const significantLevels = Array.from(levels.entries())
      .filter(([price, touches]) => touches >= this.config.srMinTouches)
      .sort((a, b) => b[1] - a[1]) // Sort by touch count
      .slice(0, 10); // Top 10 levels

    // Classify as support or resistance relative to entry
    significantLevels.forEach(([price, touches]) => {
      const level = {
        price,
        touches,
        distance: Math.abs(price - entryPrice),
        percentFromEntry: ((price - entryPrice) / entryPrice * 100).toFixed(2),
        strength: this.calculateLevelStrength(touches, price, recentCandles)
      };

      if (price < entryPrice) {
        this.entryAnalysis.supportLevels.push(level);
      } else {
        this.entryAnalysis.resistanceLevels.push(level);
      }
    });

    // Sort by distance from entry
    this.entryAnalysis.supportLevels.sort((a, b) => a.distance - b.distance);
    this.entryAnalysis.resistanceLevels.sort((a, b) => a.distance - b.distance);

    console.log(`🎚️ S/R Levels from entry:`);
    console.log(`   Supports: ${this.entryAnalysis.supportLevels.length} levels below $${entryPrice.toFixed(2)}`);
    console.log(`   Resistances: ${this.entryAnalysis.resistanceLevels.length} levels above $${entryPrice.toFixed(2)}`);
  }

  /**
   * DYNAMIC TREND CALCULATION
   */
  calculateDynamicTrends(candles, entryPrice) {
    const multiplier = this.config.timeframeMultipliers[this.entryAnalysis.timeframe];

    // Calculate MAs at entry point
    const shortMA = this.calculateMA(candles, this.config.trendShortPeriod);
    const mediumMA = this.calculateMA(candles, this.config.trendMediumPeriod);
    const longMA = this.calculateMA(candles, this.config.trendLongPeriod);

    // Determine trend strength and direction
    this.entryAnalysis.trendAnalysis = {
      shortTrend: {
        ma: shortMA,
        direction: entryPrice > shortMA ? 'BULLISH' : 'BEARISH',
        distance: ((entryPrice - shortMA) / shortMA * 100).toFixed(2),
        strength: Math.abs(entryPrice - shortMA) / shortMA
      },
      mediumTrend: {
        ma: mediumMA,
        direction: entryPrice > mediumMA ? 'BULLISH' : 'BEARISH',
        distance: ((entryPrice - mediumMA) / mediumMA * 100).toFixed(2),
        strength: Math.abs(entryPrice - mediumMA) / mediumMA
      },
      longTrend: {
        ma: longMA,
        direction: entryPrice > longMA ? 'BULLISH' : 'BEARISH',
        distance: ((entryPrice - longMA) / longMA * 100).toFixed(2),
        strength: Math.abs(entryPrice - longMA) / longMA
      },
      overallTrend: this.determineOverallTrend(entryPrice, shortMA, mediumMA, longMA),
      trendAlignment: this.checkTrendAlignment(shortMA, mediumMA, longMA),
      entryQuality: this.assessEntryQuality(entryPrice, shortMA, mediumMA, longMA)
    };

    console.log(`📈 Trend Analysis at entry:`);
    console.log(`   Overall: ${this.entryAnalysis.trendAnalysis.overallTrend}`);
    console.log(`   Alignment: ${this.entryAnalysis.trendAnalysis.trendAlignment}`);
    console.log(`   Entry Quality: ${this.entryAnalysis.trendAnalysis.entryQuality}`);
  }

  /**
   * CALCULATE PRICE TARGETS BASED ON ENTRY
   */
  calculatePriceTargets(direction, entryPrice) {
    const atr = this.calculateATR(this.ogz.timeframeData[this.entryAnalysis.timeframe]?.candles || []);

    if (direction === 'buy') {
      this.entryAnalysis.priceTargets = {
        conservative: entryPrice + (atr * 1),    // 1x ATR
        moderate: entryPrice + (atr * 2),        // 2x ATR
        aggressive: entryPrice + (atr * 3),      // 3x ATR
        fibonacci: {
          target1: this.entryAnalysis.fibonacciLevels[1.272]?.price,
          target2: this.entryAnalysis.fibonacciLevels[1.618]?.price,
          target3: this.entryAnalysis.fibonacciLevels[2.0]?.price
        },
        resistance: this.entryAnalysis.resistanceLevels[0]?.price
      };

      this.entryAnalysis.stopLevels = {
        tight: entryPrice - (atr * 0.5),
        normal: entryPrice - (atr * 1),
        wide: entryPrice - (atr * 1.5),
        support: this.entryAnalysis.supportLevels[0]?.price,
        fibonacci: this.entryAnalysis.fibonacciLevels[0.236]?.price
      };
    } else {
      this.entryAnalysis.priceTargets = {
        conservative: entryPrice - (atr * 1),
        moderate: entryPrice - (atr * 2),
        aggressive: entryPrice - (atr * 3),
        fibonacci: {
          target1: this.entryAnalysis.fibonacciLevels[1.272]?.price,
          target2: this.entryAnalysis.fibonacciLevels[1.618]?.price,
          target3: this.entryAnalysis.fibonacciLevels[2.0]?.price
        },
        support: this.entryAnalysis.supportLevels[0]?.price
      };

      this.entryAnalysis.stopLevels = {
        tight: entryPrice + (atr * 0.5),
        normal: entryPrice + (atr * 1),
        wide: entryPrice + (atr * 1.5),
        resistance: this.entryAnalysis.resistanceLevels[0]?.price,
        fibonacci: this.entryAnalysis.fibonacciLevels[0.786]?.price
      };
    }

    console.log(`🎯 Price Targets from entry $${entryPrice.toFixed(2)}:`);
    console.log(`   Target 1: $${this.entryAnalysis.priceTargets.conservative.toFixed(2)}`);
    console.log(`   Target 2: $${this.entryAnalysis.priceTargets.moderate.toFixed(2)}`);
    console.log(`   Stop Loss: $${this.entryAnalysis.stopLevels.normal.toFixed(2)}`);
  }

  /**
   * IDENTIFY KEY LEVELS NEAR ENTRY
   */
  identifyKeyLevels(entryPrice) {
    const keyLevels = [];
    const threshold = entryPrice * 0.02; // 2% from entry

    // Check Fibonacci levels
    Object.entries(this.entryAnalysis.fibonacciLevels).forEach(([level, data]) => {
      if (Math.abs(data.price - entryPrice) < threshold) {
        keyLevels.push({
          type: 'FIBONACCI',
          level: level,
          price: data.price,
          distance: data.distance,
          importance: this.getFibImportance(level)
        });
      }
    });

    // Check S/R levels
    this.entryAnalysis.supportLevels.forEach(level => {
      if (level.distance < threshold) {
        keyLevels.push({
          type: 'SUPPORT',
          price: level.price,
          distance: level.distance,
          touches: level.touches,
          importance: level.strength
        });
      }
    });

    this.entryAnalysis.resistanceLevels.forEach(level => {
      if (level.distance < threshold) {
        keyLevels.push({
          type: 'RESISTANCE',
          price: level.price,
          distance: level.distance,
          touches: level.touches,
          importance: level.strength
        });
      }
    });

    // Sort by distance from entry
    keyLevels.sort((a, b) => a.distance - b.distance);
    this.entryAnalysis.keyLevels = keyLevels;

    if (keyLevels.length > 0) {
      console.log(`⚠️ KEY LEVELS near entry:`);
      keyLevels.forEach(level => {
        console.log(`   ${level.type} at $${level.price.toFixed(2)} (${((level.distance/entryPrice)*100).toFixed(2)}% away)`);
      });
    }
  }

  /**
   * BROADCAST LEVELS TO DASHBOARD
   */
  broadcastLevels() {
    if (this.ogz.webSocketManager) {
      const data = {
        type: 'entry_analysis',
        data: {
          entry: {
            price: this.entryAnalysis.entryPrice,
            time: this.entryAnalysis.entryTime,
            direction: this.entryAnalysis.direction
          },
          fibonacci: Object.entries(this.entryAnalysis.fibonacciLevels).map(([level, data]) => ({
            level,
            price: data.price,
            percent: data.percentFromEntry
          })),
          support: this.entryAnalysis.supportLevels.slice(0, 5),
          resistance: this.entryAnalysis.resistanceLevels.slice(0, 5),
          trends: this.entryAnalysis.trendAnalysis,
          targets: this.entryAnalysis.priceTargets,
          stops: this.entryAnalysis.stopLevels,
          keyLevels: this.entryAnalysis.keyLevels
        },
        timestamp: Date.now()
      };

      this.ogz.webSocketManager.broadcast(this.ogz.config.guiWebSocketPort, data);
    }
  }

  /**
   * LOG ENTRY SUMMARY
   */
  logEntrySummary() {
