// Advanced Quantum Risk Management System
// Based on "valueinsteadofegocodeandfunctionnames.md" mathematical formulas
// Implements Kelly Criterion, Sharpe optimization, CVaR, and regime-adaptive sizing

const EventEmitter = require('events');

class QuantumRiskManager extends EventEmitter {
  constructor(config = {}) {
    super();

    this.config = {
      // Kelly Criterion parameters
      kellyMultiplier: config.kellyMultiplier || 0.25,  // Use 25% Kelly for safety
      maxKellyFraction: config.maxKellyFraction || 0.25,
      minKellyFraction: config.minKellyFraction || 0.01,

      // Risk parameters
      maxDrawdown: config.maxDrawdown || 0.20,          // 20% max drawdown
      riskFreeRate: config.riskFreeRate || 0.02,        // 2% annual risk-free rate
      confidenceLevel: config.confidenceLevel || 0.95,   // 95% CVaR

      // Regime detection
      regimeWindow: config.regimeWindow || 100,
      volatilityThreshold: config.volatilityThreshold || 0.02,

      // Portfolio constraints
      maxPositionSize: config.maxPositionSize || 0.10,   // 10% max per position
      minPositionSize: config.minPositionSize || 0.001,  // 0.1% minimum
      maxLeverage: config.maxLeverage || 2.0,

      // Dynamic adjustment
      useDynamicAdjustment: config.useDynamicAdjustment !== false,
      adaptiveWindow: config.adaptiveWindow || 50
    };

    // Historical tracking
    this.history = {
      returns: [],
      positions: [],
      sharpeRatios: [],
      drawdowns: [],
      regimes: []
    };

    // Current state
    this.state = {
      currentRegime: 'NORMAL',
      currentVolatility: 0,
      currentSharpe: 0,
      currentDrawdown: 0,
      winRate: 0.5,
      avgWin: 0,
      avgLoss: 0,
      kellyFraction: 0.02
    };

    console.log('💎 Quantum Risk Manager initialized');
    console.log(`📊 Kelly multiplier: ${this.config.kellyMultiplier}`);
    console.log(`🛡️ Max drawdown: ${(this.config.maxDrawdown * 100).toFixed(1)}%`);
  }

  /**
   * KELLY CRITERION CALCULATION
   * f* = (p*b - q) / b
   * where p = win probability, q = loss probability, b = win/loss ratio
   */
  calculateKellyCriterion(winProb, avgWin, avgLoss) {
    if (avgLoss === 0 || avgWin <= 0) return 0;

    const lossProb = 1 - winProb;
    const winLossRatio = avgWin / Math.abs(avgLoss);

    // Kelly formula: f* = (p*b - q) / b
    const kellyFraction = (winProb * winLossRatio - lossProb) / winLossRatio;

    // Apply safety multiplier (fractional Kelly)
    const safeKelly = kellyFraction * this.config.kellyMultiplier;

    // Enforce bounds
    return Math.max(
      this.config.minKellyFraction,
      Math.min(this.config.maxKellyFraction, safeKelly)
    );
  }

  /**
   * SHARPE RATIO CALCULATION
   * Sharpe = (mean_return - risk_free_rate) / std_deviation
   */
  calculateSharpeRatio(returns = null) {
    const data = returns || this.history.returns;
    if (data.length < 2) return 0;

    // Calculate mean return
    const meanReturn = data.reduce((a, b) => a + b, 0) / data.length;

    // Calculate standard deviation
    const variance = data.reduce((sum, ret) => 
      sum + Math.pow(ret - meanReturn, 2), 0) / data.length;
    const stdDev = Math.sqrt(variance);

    if (stdDev === 0) return 0;

    // Daily to annual conversion (assuming 252 trading days)
    const annualMean = meanReturn * 252;
    const annualStdDev = stdDev * Math.sqrt(252);

    // Sharpe ratio
    return (annualMean - this.config.riskFreeRate) / annualStdDev;
  }

  /**
   * CONDITIONAL VALUE AT RISK (CVaR)
   * Expected loss beyond VaR threshold
   */
  calculateCVaR(returns = null, confidenceLevel = null) {
    const data = returns || this.history.returns;
    const confidence = confidenceLevel || this.config.confidenceLevel;

    if (data.length < 10) return 0;

    // Sort returns ascending
    const sorted = [...data].sort((a, b) => a - b);

    // Find VaR index
    const varIndex = Math.floor((1 - confidence) * sorted.length);

    // Calculate average of returns below VaR
    const tailReturns = sorted.slice(0, varIndex + 1);
    const cvar = tailReturns.reduce((a, b) => a + b, 0) / tailReturns.length;

    return Math.abs(cvar); // Return as positive risk measure
  }

  /**
   * MAXIMUM DRAWDOWN CALCULATION
   */
  calculateMaxDrawdown(equity = null) {
    const data = equity || this.history.positions.map(p => p.equity);
    if (data.length < 2) return 0;

    let maxDrawdown = 0;
    let peak = data[0];

    for (let i = 1; i < data.length; i++) {
      if (data[i] > peak) {
        peak = data[i];
      }
      const drawdown = (peak - data[i]) / peak;
      maxDrawdown = Math.max(maxDrawdown, drawdown);
    }

    return maxDrawdown;
  }

  /**
   * VOLATILITY CALCULATION (GARCH-style)
   * σₜ² = ω + α·εₜ₋₁² + β·σₜ₋₁²
   */
  calculateVolatility(returns = null, useGARCH = false) {
    const data = returns || this.history.returns.slice(-this.config.regimeWindow);

    if (data.length < 2) return 0.01; // Default volatility

    if (useGARCH) {
      // Simplified GARCH(1,1) estimation
      const omega = 0.000001;  // Long-term variance
      const alpha = 0.1;       // Weight on previous shock
      const beta = 0.85;       // Weight on previous variance

      let variance = Math.pow(data[0], 2);

      for (let i = 1; i < data.length; i++) {
        const shock = Math.pow(data[i], 2);
        variance = omega + alpha * shock + beta * variance;
      }

      return Math.sqrt(variance);
    } else {
      // Simple standard deviation
      const mean = data.reduce((a, b) => a + b, 0) / data.length;
      const variance = data.reduce((sum, ret) => 
        sum + Math.pow(ret - mean, 2), 0) / data.length;
      return Math.sqrt(variance);
    }
  }

  /**
   * REGIME DETECTION
   * Identifies market regimes: BULL, BEAR, NORMAL, VOLATILE
   */
  detectMarketRegime(marketData) {
    const returns = marketData.returns || this.history.returns.slice(-this.config.regimeWindow);

    if (returns.length < 10) return 'NORMAL';

    // Calculate regime indicators
    const meanReturn = returns.reduce((a, b) => a + b, 0) / returns.length;
    const volatility = this.calculateVolatility(returns);
    const trend = this.calculateTrend(returns);

    // Classify regime
    let regime = 'NORMAL';

    if (volatility > this.config.volatilityThreshold * 2) {
      regime = 'EXTREME_VOLATILITY';
    } else if (volatility > this.config.volatilityThreshold) {
      regime = 'VOLATILE';
    } else if (trend > 0.001 && meanReturn > 0) {
      regime = 'BULL';
    } else if (trend < -0.001 && meanReturn < 0) {
      regime = 'BEAR';
    }

    this.state.currentRegime = regime;
    this.state.currentVolatility = volatility;

    return regime;
  }

  /**
   * TREND CALCULATION
   * Simple linear regression slope
   */
  calculateTrend(data) {
    if (data.length < 2) return 0;

    const n = data.length;
    const indices = Array.from({length: n}, (_, i) => i);

    const sumX = indices.reduce((a, b) => a + b, 0);
    const sumY = data.reduce((a, b) => a + b, 0);
    const sumXY = indices.reduce((sum, x, i) => sum + x * data[i], 0);
    const sumX2 = indices.reduce((sum, x) => sum + x * x, 0);

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);

    return slope;
  }

  /**
   * OPTIMAL POSITION SIZE CALCULATION
   * Combines Kelly, Sharpe, CVaR, and regime adjustments
   */
  calculateOptimalPosition(signal, marketData, capital) {
    console.log('🎯 Calculating optimal position size...');

    // Update statistics
    this.updateStatistics(marketData);

    // Detect current regime
    const regime = this.detectMarketRegime(marketData);

    // Base Kelly calculation
    const kellyFraction = this.calculateKellyCriterion(
      this.state.winRate,
      this.state.avgWin,
      this.state.avgLoss
    );

    // Sharpe-based adjustment
    const sharpe = this.calculateSharpeRatio();
    const sharpeMultiplier = Math.max(0.5, Math.min(1.5, sharpe / 2));

    // CVaR-based risk adjustment
    const cvar = this.calculateCVaR();
    const cvarMultiplier = cvar > 0.05 ? 0.5 : 1.0; // Reduce size if CVaR > 5%

    // Regime-based adjustment
    const regimeMultipliers = {
      'BULL': 1.2,
      'BEAR': 0.8,
      'NORMAL': 1.0,
      'VOLATILE': 0.6,
      'EXTREME_VOLATILITY': 0.3
    };
    const regimeMultiplier = regimeMultipliers[regime];

    // Drawdown protection
    const currentDD = this.calculateMaxDrawdown();
    const ddMultiplier = currentDD > this.config.maxDrawdown * 0.5 ? 
      0.5 : 1.0;

    // Combine all factors
    let optimalFraction = kellyFraction * 
                          sharpeMultiplier * 
                          cvarMultiplier * 
                          regimeMultiplier * 
                          ddMultiplier;

    // Apply position size constraints
    optimalFraction = Math.max(
      this.config.minPositionSize,
      Math.min(this.config.maxPositionSize, optimalFraction)
    );

    // Calculate position size in capital
    const positionSize = capital * optimalFraction;

    // Store for history
    this.state.kellyFraction = optimalFraction;

    const result = {
      size: positionSize,
      fraction: optimalFraction,
      kelly: kellyFraction,
      adjustments: {
        sharpe: sharpeMultiplier,
        cvar: cvarMultiplier,
        regime: regimeMultiplier,
        drawdown: ddMultiplier
      },
      metrics: {
        sharpeRatio: sharpe,
        cvar: cvar,
        maxDrawdown: currentDD,
        volatility: this.state.currentVolatility,
        regime: regime
      },
      recommendation: this.generateRecommendation(optimalFraction, regime)
    };

    console.log(`💰 Optimal position: $${positionSize.toFixed(2)} (${(optimalFraction * 100).toFixed(2)}%)`);
    console.log(`📊 Regime: ${regime}, Sharpe: ${sharpe.toFixed(2)}, CVaR: ${(cvar * 100).toFixed(1)}%`);

    this.emit('position_calculated', result);

    return result;
  }

  /**
   * UPDATE STATISTICS
   * Updates win rate, average win/loss from recent history
   */
  updateStatistics(marketData) {
    const recentTrades = marketData.trades || this.history.positions.slice(-50);

    if (recentTrades.length > 0) {
      const wins = recentTrades.filter(t => t.pnl > 0);
      const losses = recentTrades.filter(t => t.pnl < 0);

      this.state.winRate = wins.length / recentTrades.length;
      this.state.avgWin = wins.length > 0 ? 
        wins.reduce((sum, t) => sum + t.pnl, 0) / wins.length : 0;
      this.state.avgLoss = losses.length > 0 ? 
        losses.reduce((sum, t) => sum + t.pnl, 0) / losses.length : 0;
    }

    // Update Sharpe
    this.state.currentSharpe = this.calculateSharpeRatio();

    // Update drawdown
    this.state.currentDrawdown = this.calculateMaxDrawdown();
  }

  /**
   * GENERATE RECOMMENDATION
   */
  generateRecommendation(fraction, regime) {
    if (fraction < 0.01) {
      return 'SKIP - Risk too high';
    } else if (fraction < 0.02) {
      return 'SMALL - Proceed with caution';
    } else if (fraction < 0.05) {
      return 'MODERATE - Normal position';
    } else if (fraction < 0.10) {
      return 'LARGE - High confidence';
    } else {
      return 'MAX - Exceptional opportunity';
    }
  }

  /**
   * RISK CHECK
   * Validates if a trade should be taken based on risk parameters
   */
  validateTrade(position, capital) {
    const checks = {
      drawdownOk: this.state.currentDrawdown < this.config.maxDrawdown,
      positionSizeOk: position.size <= capital * this.config.maxPositionSize,
      leverageOk: (position.size / capital) <= this.config.maxLeverage,
      volatilityOk: this.state.currentVolatility < this.config.volatilityThreshold * 3,
      sharpeOk: this.state.currentSharpe > -1
    };

    const allChecks = Object.values(checks).every(check => check);

    return {
      approved: allChecks,
      checks: checks,
      warnings: this.generateWarnings(checks)
    };
  }

  /**
   * GENERATE WARNINGS
   */
  generateWarnings(checks) {
    const warnings = [];

    if (!checks.drawdownOk) {
      warnings.push('⚠️ Maximum drawdown exceeded');
    }
    if (!checks.volatilityOk) {
      warnings.push('⚠️ Extreme volatility detected');
    }
    if (!checks.sharpeOk) {
      warnings.push('⚠️ Poor risk-adjusted returns');
    }

    return warnings;
  }

  /**
   * ADD TRADE RESULT
   * Records trade outcome for continuous learning
   */
  addTradeResult(trade) {
    // Add to history
    this.history.positions.push(trade);
    this.history.returns.push(trade.pnl / trade.size);

    // Trim history to window
    if (this.history.returns.length > this.config.adaptiveWindow * 2) {
      this.history.returns.shift();
      this.history.positions.shift();
    }

    // Recalculate metrics
    this.updateStatistics({ trades: this.history.positions });

    // Emit update
    this.emit('metrics_updated', {
      sharpe: this.state.currentSharpe,
      winRate: this.state.winRate,
      drawdown: this.state.currentDrawdown
    });
  }

  /**
   * GET RISK REPORT
   */
  getRiskReport() {
    return {
      current: {
