  /**
   * Save pattern memory to disk
   */
  saveToDisk() {
    if (!this.options.persistToDisk) return;

    try {
      const data = JSON.stringify({
        count: this.patternCount,
        patterns: this.memory,
        timestamp: new Date().toISOString()
      });

