      const safetyResult = this.tradingSafetyNet.validateTrade(tradeRequest, analysisData);
      if (!safetyResult.approved) {
        console.log(`ðŸ›¡ï¸ TRADE BLOCKED by Safety Net: ${safetyResult.reason}`);
        return false;
      }
    }

    // Validate inputs
    if (!price || price <= 0) {
      console.log('âŒ Invalid price for position entry');
      return false;
    }

    if (!['buy', 'sell'].includes(direction)) {
      console.log('âŒ Invalid direction. Must be "buy" or "sell"');
      return false;
